# ============================================================
# FANTASY MODEL 3.1 - GUARDED WEEKLY ONLINE RETRAIN
# ============================================================
# Fits a current-season challenger on top of the immutable historical store.
# 2026 rows are never mixed into the historical CSV. Hyperparameters stay
# frozen from historical validation; only model weights are updated.
#
# Honest in-season validation:
#   Week K prediction is generated by a model trained only through Week K-1.
# The final model is then fit through the latest fully completed week and may
# enter production only if cumulative 2026 OOS gates pass.

source("config.R")
ensure_packages(c("dplyr", "readr", "xgboost"))
source("R/weekly_engine_31.R")

dir.create("models/online_archive", recursive = TRUE, showWarnings = FALSE)
dir.create("output", recursive = TRUE, showWarnings = FALSE)

hist_path <- "data/processed/weekly_model_table_2_3.csv"
online_path <- paste0("data/online/weekly_training_", CURRENT_SEASON, "_latest.csv")
hist_manifest_path <- "output/weekly_3_1_champion_manifest.csv"

for (p in c(hist_path, online_path, hist_manifest_path)) {
  if (!file.exists(p)) stop("[3.1 ONLINE TRAIN] Missing required file: ", p)
}

historical <- readr::read_csv(hist_path, show_col_types = FALSE, progress = FALSE)
online <- readr::read_csv(online_path, show_col_types = FALSE, progress = FALSE)
hist_manifest <- readr::read_csv(hist_manifest_path, show_col_types = FALSE, progress = FALSE)

historical$season <- suppressWarnings(as.integer(historical$season))
historical$week <- suppressWarnings(as.integer(historical$week))
historical$player_id <- as.character(historical$player_id)
online$season <- suppressWarnings(as.integer(online$season))
online$week <- suppressWarnings(as.integer(online$week))
online$player_id <- as.character(online$player_id)

missing_hist <- setdiff(c("season","week","player_id","position","weekly_fppg", MODEL25_SAFE_FEATURES), names(historical))
missing_online <- setdiff(c(
  "season","week","player_id","position","weekly_fppg","actual_fppg",
  "production_base_31","starter_cohort","relevant_cohort", MODEL31_SAFE_FEATURES
), names(online))
if (length(missing_hist)) stop("[3.1 ONLINE TRAIN] Historical store missing: ", paste(missing_hist, collapse = ", "))
if (length(missing_online)) stop("[3.1 ONLINE TRAIN] Current-season store missing: ", paste(missing_online, collapse = ", "))

cutoff_week <- max(online$week[is.finite(online$week)], na.rm = TRUE)
if (!is.finite(cutoff_week)) stop("[3.1 ONLINE TRAIN] Invalid current-season cutoff.")

# Current-season observations matter more than old rows, but history is never
# discarded. The 1.5x cap is intentionally modest to avoid chasing one month.
online_training_weight <- function(d) {
  ifelse(suppressWarnings(as.integer(d$season)) == CURRENT_SEASON, 1.5, 1.0)
}

ONLINE_ALPHA_GRID_31 <- c(0, 0.05, 0.10, 0.15, 0.20, 0.25)
ONLINE_ALPHA_CAP_31 <- c(QB = 0.10, RB = 0.15, WR = 0.15, TE = 0.12)

select_online_alpha31 <- function(prior_oof, pos) {
  if (!nrow(prior_oof)) return(0)
  weeks <- unique(suppressWarnings(as.integer(prior_oof$week)))
  weeks <- weeks[is.finite(weeks)]
  if (length(weeks) < 2 || nrow(prior_oof) < 40) return(0)
  cap <- as.numeric(ONLINE_ALPHA_CAP_31[[pos]])
  grid <- ONLINE_ALPHA_GRID_31[ONLINE_ALPHA_GRID_31 <= cap + 1e-9]
  score <- vapply(grid, function(a) wk31_decision_score(prior_oof, a), numeric(1))
  if (!any(is.finite(score))) return(0)
  best <- min(score[is.finite(score)])
  near <- grid[is.finite(score) & score <= best + 0.001]
  if (!length(near)) 0 else min(near)
}

oof_rows <- list()
promotion_rows <- list()
manifest_rows <- list()

for (pos in POSITIONS) {
  hp <- historical[as.character(historical$position) == pos, , drop = FALSE]
  op <- online[as.character(online$position) == pos, , drop = FALSE]
  if (!nrow(hp) || !nrow(op)) next

  hist_model_path <- paste0("models/weekly_3_1_direct_", pos, ".json")
  hist_meta_path <- paste0("models/weekly_3_1_direct_", pos, "_meta.rds")
  if (!file.exists(hist_model_path) || !file.exists(hist_meta_path)) {
    warning("[3.1 ONLINE TRAIN] Historical 3.1 model missing for ", pos, "; skipping.")
    next
  }
  meta_hist <- readRDS(hist_meta_path)
  cfg <- meta_hist$config
  if (is.null(cfg) || !is.data.frame(cfg) || !nrow(cfg)) {
    stop("[3.1 ONLINE TRAIN] Frozen historical config unavailable for ", pos, ".")
  }

  hm <- hist_manifest[as.character(hist_manifest$position) == pos, , drop = FALSE]
  historical_guardrail <- nrow(hm) > 0 &&
    isTRUE(wk25_bool(hm$promoted_for_2026[1])) &&
    isTRUE(meta_hist$promoted_for_2026)

  weeks <- sort(unique(op$week[is.finite(op$week)]))
  prior_oof <- data.frame()
  pos_oof <- list()

  for (target_week in weeks) {
    train_online <- op[op$week < target_week, , drop = FALSE]
    train <- dplyr::bind_rows(hp, train_online)
    extra_w <- online_training_weight(train)

    fit <- wk31_fit(
      train, pos, cfg,
      target_col = "weekly_fppg",
      seed = SEED + 31000L + target_week * 100L + match(pos, POSITIONS),
      extra_weight = extra_w
    )

    test <- op[op$week == target_week, , drop = FALSE]
    direct <- wk31_predict(fit, test)

    # Alpha for Week K is selected ONLY from Weeks < K.
    alpha <- select_online_alpha31(prior_oof, pos)
    candidate <- pmax(
      0,
      wk31_num(test$production_base_31) +
        alpha * (direct - wk31_num(test$production_base_31))
    )

    cur <- test
    cur$direct_fppg_31 <- direct
    cur$blend_alpha_31 <- alpha
    cur$candidate_fppg_31 <- candidate
    cur$online_train_through_week_31 <- target_week - 1L
    cur$online_target_week_31 <- target_week
    pos_oof[[length(pos_oof) + 1L]] <- cur
    prior_oof <- dplyr::bind_rows(prior_oof, cur)
  }

  oof <- dplyr::bind_rows(pos_oof) |>
    dplyr::arrange(week, player_id)
  if (!nrow(oof)) next
  oof_rows[[length(oof_rows) + 1L]] <- oof

  final_alpha <- select_online_alpha31(oof, pos)
  gate <- wk31_promotion_gate(oof, pos)

  metrics <- wk31_cohort_metrics(oof, "candidate_fppg_31", "production_base_31")
  all_m <- metrics[metrics$cohort == "All", , drop = FALSE]
  st_m <- metrics[metrics$cohort == "Starter", , drop = FALSE]
  rel_m <- metrics[metrics$cohort == "Relevant", , drop = FALSE]

  oos_weeks <- length(unique(oof$week))
  starter_n <- if (nrow(st_m)) suppressWarnings(as.integer(st_m$candidate_n[1])) else 0L
  sample_gate <- oos_weeks >= 3 && nrow(oof) >= 60 && starter_n >= 12
  online_gate <- isTRUE(gate$promoted_for_2026[1]) && is.finite(final_alpha) && final_alpha > 0
  promoted <- historical_guardrail && sample_gate && online_gate

  # Final fit retains ALL historical rows plus every honestly audited 2026 row
  # through the cutoff. Nothing is dropped when current-season data is added.
  full_train <- dplyr::bind_rows(hp, op)
  full_weight <- online_training_weight(full_train)
  final_fit <- wk31_fit(
    full_train, pos, cfg,
    target_col = "weekly_fppg",
    seed = SEED + 31900L + cutoff_week * 100L + match(pos, POSITIONS),
    extra_weight = full_weight
  )

  archive_model <- sprintf(
    "models/online_archive/weekly_3_1_online_%s_through_week_%02d.json",
    pos, cutoff_week
  )
  archive_meta <- sprintf(
    "models/online_archive/weekly_3_1_online_%s_through_week_%02d_meta.rds",
    pos, cutoff_week
  )
  pointer_model <- paste0("models/weekly_3_1_online_", pos, ".json")
  pointer_meta <- paste0("models/weekly_3_1_online_", pos, "_meta.rds")

  meta_out <- list(
    position = pos,
    features = final_fit$features,
    config = cfg,
    nrounds = final_fit$nrounds,
    n_train = final_fit$n_train,
    trained_through_season = CURRENT_SEASON,
    trained_through_week = cutoff_week,
    historical_rows = nrow(hp),
    current_season_rows = nrow(op),
    current_season_weight = 1.5,
    final_alpha = final_alpha,
    promoted_for_production = promoted,
    historical_guardrail = historical_guardrail,
    sample_gate = sample_gate,
    online_gate = online_gate,
    historical_md5 = unname(tools::md5sum(hist_path)),
    online_training_md5 = unname(tools::md5sum(online_path)),
    generated_at_utc = format(Sys.time(), "%Y-%m-%dT%H:%M:%SZ", tz = "UTC")
  )

  # Never overwrite a past cutoff model. The moving pointer may update weekly.
  if (!file.exists(archive_model)) xgboost::xgb.save(final_fit$model, archive_model)
  if (!file.exists(archive_meta)) saveRDS(meta_out, archive_meta)
  xgboost::xgb.save(final_fit$model, pointer_model)
  saveRDS(meta_out, pointer_meta)

  promotion_rows[[length(promotion_rows) + 1L]] <- data.frame(
    position = pos,
    cutoff_week = cutoff_week,
    historical_guardrail = historical_guardrail,
    oos_weeks = oos_weeks,
    oos_rows = nrow(oof),
    starter_rows = starter_n,
    sample_gate = sample_gate,
    online_gate = online_gate,
    promoted_for_production = promoted,
    final_alpha = final_alpha,
    all_base_MAE = if (nrow(all_m)) all_m$base_MAE[1] else NA_real_,
    all_candidate_MAE = if (nrow(all_m)) all_m$candidate_MAE[1] else NA_real_,
    starter_base_MAE = if (nrow(st_m)) st_m$base_MAE[1] else NA_real_,
    starter_candidate_MAE = if (nrow(st_m)) st_m$candidate_MAE[1] else NA_real_,
    relevant_base_MAE = if (nrow(rel_m)) rel_m$base_MAE[1] else NA_real_,
    relevant_candidate_MAE = if (nrow(rel_m)) rel_m$candidate_MAE[1] else NA_real_,
    failed_checks = paste(
      c(
        if (!historical_guardrail) "historical_guardrail" else NULL,
        if (!sample_gate) "sample_gate" else NULL,
        if (!online_gate) paste0("online_gate:", gate$failed_checks[1]) else NULL,
        if (!is.finite(final_alpha) || final_alpha <= 0) "alpha_zero" else NULL
      ),
      collapse = ";"
    ),
    stringsAsFactors = FALSE
  )

  manifest_rows[[length(manifest_rows) + 1L]] <- data.frame(
    position = pos,
    cutoff_week = cutoff_week,
    model_path = pointer_model,
    archive_model_path = archive_model,
    archive_meta_path = archive_meta,
    trained_rows = final_fit$n_train,
    historical_rows = nrow(hp),
    current_season_rows = nrow(op),
    final_alpha = final_alpha,
    promoted_for_production = promoted,
    stringsAsFactors = FALSE
  )

  cat("[3.1 ONLINE TRAIN] ", pos,
      " | cutoff=", cutoff_week,
      " | hist=", nrow(hp),
      " | 2026=", nrow(op),
      " | OOS weeks=", oos_weeks,
      " | alpha=", sprintf("%.2f", final_alpha),
      " | promote=", promoted, "\n", sep = "")
}

oof_all <- dplyr::bind_rows(oof_rows)
promotion <- dplyr::bind_rows(promotion_rows)
manifest <- dplyr::bind_rows(manifest_rows)

if (!nrow(manifest)) stop("[3.1 ONLINE TRAIN] No position model was trained.")

readr::write_csv(oof_all, paste0("output/weekly_3_1_online_oof_", CURRENT_SEASON, ".csv"))
readr::write_csv(promotion, "output/weekly_3_1_online_promotion.csv")
readr::write_csv(manifest, "output/weekly_3_1_online_manifest.csv")

report <- c(
  "FANTASY MODEL 3.1 - WEEKLY ONLINE RETRAIN",
  paste0("Generated: ", format(Sys.time(), "%Y-%m-%d %H:%M:%S %z")),
  paste0("Current-season cutoff: Week ", cutoff_week),
  "",
  "DATA PRESERVATION",
  paste0("- Historical source remains immutable: ", hist_path),
  paste0("- Historical md5: ", unname(tools::md5sum(hist_path))),
  paste0("- Current-season immutable cutoff: data/online/weekly_training_", CURRENT_SEASON,
         "_through_week_", sprintf("%02d", cutoff_week), ".csv"),
  "- Final fitting retains all historical rows plus all honestly audited current-season rows.",
  "- Hyperparameters are not retuned on 2026 outcomes.",
  "",
  "PROMOTION"
)
for (i in seq_len(nrow(promotion))) {
  x <- promotion[i, ]
  report <- c(report, sprintf(
    "- %s: %s | OOS weeks %d | rows %d | starter MAE %.3f -> %.3f | alpha %.2f | %s",
    x$position,
    ifelse(x$promoted_for_production, "PROMOTE ONLINE", "KEEP CURRENT PRODUCTION"),
    x$oos_weeks, x$oos_rows,
    x$starter_base_MAE, x$starter_candidate_MAE,
    x$final_alpha,
    ifelse(nzchar(x$failed_checks), x$failed_checks, "all gates passed")
  ))
}
writeLines(report, "output/weekly_3_1_online_report.txt")

cat("\n[3.1 ONLINE TRAIN] Weekly retrain complete. Past training data preserved.\n")
print(promotion)

invisible(list(cutoff_week = cutoff_week, promotion = promotion, manifest = manifest))
